        for phase in [SqliteSnapshotPhase::ReadPages, SqliteSnapshotPhase::ReconstructSnapshot, SqliteSnapshotPhase::EncodeNative] { assert!(phases.contains(&phase)); }
        let actual = Owned::new(match payload {
